import * as z from 'zod';

/**
 * Assignment position — free text shown on the customer-facing Team tab; a member without one is not
 * shown there. Blank collapses to null so clearing the field removes them from the roster, matching
 * the backend's own normalisation (`_normalize_position`). Shared by every form that sets a position.
 */
export const positionSchema = z.preprocess(
  (v) => (typeof v === 'string' ? v.trim() || null : (v ?? null)),
  z.string().max(64, { message: 'Position must not exceed 64 characters' }).nullable().optional()
);

type NumericStringMessages = {
  required?: string;
  invalidNumber?: string;
  positive?: string;
  min?: string;
  max?: string;
  integer?: string;
  finite?: string;
};

type NumericStringOpts<Required extends boolean = false> = {
  required?: Required;
  min?: number;
  max?: number;
  integer?: boolean;
  positive?: boolean;
  messages?: NumericStringMessages;
};

type PositiveIntPresetOpts = {
  max: number;
  requiredMessage: string;
  maxMessage: string;
  integerMessage?: string;
  positiveMessage?: string;
};

export const positiveIntPreset = (opts: PositiveIntPresetOpts) =>
  z.preprocess(
    (val) => (val === '' || val === null || val === undefined ? null : Number(val)),
    z
      .number({ message: opts.requiredMessage })
      .int(opts.integerMessage ? { message: opts.integerMessage } : undefined)
      .positive({ message: opts.positiveMessage ?? 'Must be a positive number' })
      .max(opts.max, { message: opts.maxMessage })
  );

type NonNegativeIntPresetOpts = {
  max: number;
  requiredMessage: string;
  maxMessage: string;
  integerMessage?: string;
  minMessage?: string;
};

// same shape as positiveIntPreset, but allows 0 (e.g. a count where 0 means "off")
export const nonNegativeIntPreset = (opts: NonNegativeIntPresetOpts) =>
  z.preprocess(
    (val) => (val === '' || val === null || val === undefined ? null : Number(val)),
    z
      .number({ message: opts.requiredMessage })
      .int(opts.integerMessage ? { message: opts.integerMessage } : undefined)
      .min(0, { message: opts.minMessage ?? 'Cannot be negative' })
      .max(opts.max, { message: opts.maxMessage })
  );

export const numericString = <Required extends boolean = false>(
  label: string,
  opts: NumericStringOpts<Required> = {}
) => {
  const messages = {
    required: opts.messages?.required ?? `${label} is required`,
    invalidNumber: opts.messages?.invalidNumber ?? `${label} must be a valid number`,
    positive: opts.messages?.positive ?? `${label} must be greater than 0`,
    min:
      opts.messages?.min ?? (opts.min === 0 ? `${label} cannot be negative` : `${label} must be at least ${opts.min}`),
    max: opts.messages?.max ?? `${label} must be at most ${opts.max}`,
    integer: opts.messages?.integer ?? `${label} must be a whole number`,
    finite: opts.messages?.finite ?? `${label} must be a finite number`,
  };

  const base = z
    .string({
      required_error: messages.required,
      invalid_type_error: `${label} must be a string`,
    })
    .trim();

  const stringPart = opts.required ? base.min(1, { message: messages.required }) : base;

  const refined = stringPart
    .refine((s) => opts.required || s.length === 0 || /\d/.test(s), {
      message: messages.invalidNumber,
    })
    .transform(
      (s) =>
        (s.length === 0 ? undefined : Number(s.replaceAll(',', ''))) as Required extends true
          ? number
          : number | undefined
    )
    .refine((n) => n === undefined || !Number.isNaN(n), { message: messages.invalidNumber })
    .refine((n) => n === undefined || Number.isFinite(n), { message: messages.finite })
    .refine((n) => n === undefined || !opts.positive || n > 0, { message: messages.positive })
    .refine((n) => n === undefined || opts.min === undefined || n >= opts.min, { message: messages.min })
    .refine((n) => n === undefined || opts.max === undefined || n <= opts.max, { message: messages.max })
    .refine((n) => n === undefined || !opts.integer || Number.isInteger(n), { message: messages.integer });

  return (opts.required ? refined : refined.optional()) as Required extends true
    ? typeof refined
    : z.ZodOptional<typeof refined>;
};
